import time, random

RETRYABLE = {429, 500, 529}          # rate limit, server error, overload

def call_with_backoff(send, *, max_attempts=5, base=0.5, cap=8.0):
    for attempt in range(max_attempts):
        try:
            return send()
        except Exception as e:
            status = getattr(e, "status_code", None)
            if status not in RETRYABLE:
                raise                    # deterministic: fix the request, don't retry
            if attempt == max_attempts - 1:
                raise                    # budget exhausted: fail loudly with context
            delay = min(cap, base * 2 ** attempt)
            time.sleep(delay + random.uniform(0, delay / 2))   # backoff + jitter

# Golden set: representative + previously-failing cases, each with a check.
CASES = [
    {"in": case_a, "expect": lambda o: is_valid_json(o) and "order_id" in o},
    {"in": case_b, "expect": lambda o: o.strip() == "refund"},   # prior regression
]

def score(prompt_version):
    passed = sum(c["expect"](run(c["in"], prompt_version)) for c in CASES)
    return passed / len(CASES)

before, after = score("v3"), score("v4")   # regression check on the labelled set
assert after >= before, f"regression: {before:.0%} -> {after:.0%}"
